function getWeakestUnit(){
  const weak=units.map(u=>({unit:u.id,name:u.name,missed:missedUnits["Unit "+u.id]||0,color:u.color})).sort((a,b)=>b.missed-a.missed);
  return weak[0] && weak[0].missed>0 ? weak[0] : null;
}

function readinessScore(){
  const quizScore=stats.total?Math.min(35,Math.round((stats.correct/stats.total)*35)):0;
  const volumeScore=Math.min(20,stats.total*2);
  const checkScore=Object.values(readinessChecks).filter(Boolean).length*10;
  const frqScore=aiResult&&aiResult.score?Math.min(5,aiResult.score*2):0;
  return Math.min(100,quizScore+volumeScore+checkScore+frqScore);
}

function readinessLevel(score){
  if(score>=80) return {label:"Ready to polish",box:"box-good",next:"Do timed practice and clean up weak vocabulary."};
  if(score>=55) return {label:"Getting close",box:"box-yellow",next:"Focus on your weakest unit and rewrite one FRQ part."};
  return {label:"Build points first",box:"box-warn",next:"Start with 10 MCQs and one scaffolded FRQ. Do not try to review everything at once."};
}

function setReadinessCheck(key,value){
  readinessChecks[key]=value;
  render();
}

