function unitAccuracy(unitId){
  const label='Unit '+unitId;
  const s=unitStats[label]||{attempted:0,correct:0};
  if(!s.attempted) return null;
  return s.correct/s.attempted;
}
function flashUnitMastery(unitId){
  const cards=flashcards.filter(c=>c.unit===unitId);
  if(!cards.length)return 0;
  const got=cards.filter(c=>getFlashStatus(c)==='got').length;
  return got/cards.length;
}
function unitMastery(unitId){
  const acc=unitAccuracy(unitId);
  const vocab=flashUnitMastery(unitId);
  const s=unitStats['Unit '+unitId]||{attempted:0};
  const vocabCards=flashcards.filter(c=>c.unit===unitId);
  const vocabRated=vocabCards.filter(c=>getFlashStatus(c)!=='new').length;
  // Do not manufacture a precise mastery percentage before the student has evidence.
  if(s.attempted<3 && vocabRated<3) return null;
  let weight=0, total=0;
  if(acc!==null){ total+=acc*.65; weight+=.65; }
  if(vocabRated){ total+=vocab*.35; weight+=.35; }
  return Math.max(0,Math.min(100,Math.round((total/weight)*100)));
}
function overallMastery(){
  const scores=units.map(u=>unitMastery(u.id)).filter(v=>v!==null);
  return scores.length?Math.round(scores.reduce((a,b)=>a+b,0)/scores.length):null;
}
function recommendedDifficulty(){
  const m=overallMastery();
  if(m===null)return {level:1,label:'Getting Started',desc:'Complete a few unit questions and flashcards so the app has real evidence to use.'};
  if(m>=78)return {level:3,label:'AP Challenge',desc:'More stimulus questions, model/map practice, and less support.'};
  if(m>=55)return {level:2,label:'Developing',desc:'Mixed MCQ + short FRQ parts with sentence frames.'};
  return {level:1,label:'Support Mode',desc:'Vocabulary, easier MCQs, and coached FRQ rewrites first.'};
}
function weakUnitOrder(){
  return units.map(u=>({unit:u,mastery:unitMastery(u.id),missed:missedUnits['Unit '+u.id]||0,flash:flashUnitMastery(u.id)}))
    .sort((a,b)=>(a.mastery??101)-(b.mastery??101) || b.missed-a.missed);
}
function adaptiveDeck(){
  const weak=weakUnitOrder().slice(0,3).map(x=>x.unit.id);
  let qs=quiz.filter(q=>weak.includes(Number(q[0].split(' ')[1])));
  if(!qs.length) qs=quiz.slice();
  if(adaptiveLevel===1) qs=qs.filter((q,i)=>i%3!==2);
  if(adaptiveLevel===3) qs=[...qs,...quiz.filter((q,i)=>i%5===0)];
  return qs.length?qs:quiz;
}
function getQuizSet(){
  if(qFilter==='Adaptive')return adaptiveDeck();
  return qFilter==='All'?quiz:quiz.filter(q=>q[0]===qFilter);
}
function personalizedPlanItems(){
  const rec=recommendedDifficulty();
  const weakest=weakUnitOrder().slice(0,3);
  const first=weakest[0];
  const plan=[];
  if(rec.level===1){
    plan.push({tag:'1. Build vocabulary',text:`Start with Unit ${first.unit.id} flashcards. Mark only truly memorized terms as Got it.`});
    plan.push({tag:'2. Coached MCQ',text:`Do 8 adaptive quiz questions. Read every explanation, even when correct.`});
    plan.push({tag:'3. One FRQ part',text:`Write only parts A-C for a matching FRQ. Use the rewrite button before trying the full FRQ.`});
  }else if(rec.level===2){
    plan.push({tag:'1. Target weak unit',text:`Practice Unit ${first.unit.id}: ${first.unit.name}. Do 10 MCQs, then one FRQ part.`});
    plan.push({tag:'2. Add stimulus practice',text:'Use Models & Maps and answer Identify → Describe → Explain for one visual.'});
    plan.push({tag:'3. Rewrite',text:'Rewrite one missed FRQ answer with an APHG vocab term and because/therefore.'});
  }else{
    plan.push({tag:'1. Timed AP set',text:'Take one AP Simulator section under time. Do not pause unless your teacher says so.'});
    plan.push({tag:'2. Error log',text:'For every missed MCQ, name the wrong concept and write the correct term in a because sentence.'});
    plan.push({tag:'3. Polish FRQ',text:'Practice stimulus FRQs and focus on limitations, scale of analysis, and real-world examples.'});
  }
  return plan;
}
