// Stable answer shuffling so the correct answer is not always first.
// The same question keeps the same order while it is on screen.
function hashString(str){
  let h=2166136261;
  for(let i=0;i<str.length;i++){
    h^=str.charCodeAt(i);
    h=Math.imul(h,16777619);
  }
  return h>>>0;
}
function seededShuffle(arr,seedText){
  const a=[...arr];
  let seed=hashString(seedText);
  for(let i=a.length-1;i>0;i--){
    seed=(Math.imul(seed,1664525)+1013904223)>>>0;
    const j=seed%(i+1);
    [a[i],a[j]]=[a[j],a[i]];
  }
  return a;
}
function getQuizChoices(q,index,filter){
  return seededShuffle(q[2], `${filter}-${index}-${q[1]}`);
}

