function toggleRewrite(letter){visibleRewrite[letter]=!visibleRewrite[letter];render();}
function rubricForPart(part){
  const verb=part[1];
  const base={
    Identify:'Earns 1 point for naming the correct term, process, model, indicator, or example. No full sentence is required.',
    Define:'Earns 1 point for giving an accurate meaning in your own words. Do not define the term by repeating the same word.',
    Describe:'Earns 1 point for giving one accurate characteristic, pattern, effect, or example connected to the prompt.',
    Explain:'Earns 1 point for accurate cause and effect. Use because, therefore, due to, or this leads to.',
    Apply:'Earns 1 point for using the concept correctly in the specific scenario or in a real-world example.',
    Evaluate:'Earns 1 point for naming a realistic policy/solution/judgment AND explaining why it would work.'
  };
  return base[verb]||'Earns 1 point for answering the task directly with accurate APHG content.';
}
function rewriteModel(part){return part[0]+'. '+part[3];}
function rewriteButtonHtml(part){
  const open=!!visibleRewrite[part[0]];
  return `<div style="margin-top:10px"><button class="btn-secondary btn-sm" onclick="toggleRewrite('${part[0]}')">${open?'Hide rewrite':'Show me how to rewrite'}</button>${open?`<div class="part-fix" style="margin-top:8px"><b>Strong rewrite/model:</b><br>${rewriteModel(part)}</div>`:''}</div>`;
}
function rubricMiniHtml(part){
  return `<div class="box-info" style="margin-top:8px"><b>Rubric: 1 possible point</b><p>${rubricForPart(part)}</p><p style="font-size:14px"><b>Common miss:</b> ${commonMiss(part[1])}</p></div>`;
}
function commonMiss(verb){
  if(verb==='Identify')return 'Writing a long vague sentence instead of naming the specific concept.';
  if(verb==='Define')return 'Using the term inside the definition without explaining what it means.';
  if(verb==='Describe')return 'Explaining why instead of giving a clear what/where/pattern detail.';
  if(verb==='Explain')return 'Giving a fact but not showing cause and effect with because/therefore.';
  if(verb==='Apply')return 'Giving a definition only, without connecting it to the scenario.';
  if(verb==='Evaluate')return 'Naming a policy but not explaining why it would reduce the problem.';
  return 'Being too vague for an AP reader to award the point.';
}
