 if(kind==="dtm")return `<svg viewBox="0 0 620 360"><rect width="620" height="360" rx="18" fill="#fff"/><line x1="55" y1="300" x2="580" y2="300" stroke="#334155" stroke-width="2"/><line x1="55" y1="40" x2="55" y2="300" stroke="#334155" stroke-width="2"/><polyline points="70,75 165,80 255,130 350,205 455,235 560,245" fill="none" stroke="#0f172a" stroke-width="5"/><polyline points="70,90 165,170 255,230 350,242 455,245 560,250" fill="none" stroke="#64748b" stroke-width="5" stroke-dasharray="8 6"/><path d="M170 260 C210 215,270 220,330 260" fill="none" stroke="#dc2626" stroke-width="4"/><text x="180" y="55" font-size="13">Birth rate</text><text x="185" y="190" font-size="13" fill="#64748b">Death rate</text><text x="265" y="210" font-size="13" fill="#dc2626">Natural increase</text>${[1,2,3,4,5].map((n,i)=>`<text x="${110+i*105}" y="325" text-anchor="middle" font-size="12">Stage ${n}</text>`).join("")}${title("Demographic Transition Model")}</svg>`;
 if(kind==="pyramid")return `<svg viewBox="0 0 620 360"><rect width="620" height="360" rx="18" fill="#fff"/>${title("Population Pyramid Patterns")}<line x1="310" y1="65" x2="310" y2="315" stroke="#334155"/><text x="215" y="55" text-anchor="middle" font-weight="700">Male</text><text x="405" y="55" text-anchor="middle" font-weight="700">Female</text>${[0,1,2,3,4,5,6].map((i)=>`<rect x="${310-(120-i*14)}" y="${285-i*32}" width="${120-i*14}" height="18" fill="#e2e8f0" stroke="#94a3b8"/><rect x="310" y="${285-i*32}" width="${120-i*14}" height="18" fill="#e2e8f0" stroke="#94a3b8"/>`).join("")}<text x="142" y="325" font-size="13">Wide base = youthful/growing</text><text x="420" y="325" font-size="13">Narrow base = aging/shrinking</text></svg>`;
