 if(kind==="concentric")return `<svg viewBox="0 0 620 360"><rect width="620" height="360" rx="18" fill="#fff"/>${title("Concentric Zone Model")}<circle cx="310" cy="190" r="132" fill="#f1f5f9" stroke="#475569"/><circle cx="310" cy="190" r="105" fill="#e0f2fe" stroke="#0369a1"/><circle cx="310" cy="190" r="78" fill="#dcfce7" stroke="#15803d"/><circle cx="310" cy="190" r="52" fill="#fef3c7" stroke="#b45309"/><circle cx="310" cy="190" r="25" fill="#0f172a"/><text x="310" y="194" text-anchor="middle" fill="white" font-size="12">CBD</text><text x="310" y="145" text-anchor="middle" font-size="12">Transition</text><text x="310" y="112" text-anchor="middle" font-size="12">Working Class</text><text x="310" y="82" text-anchor="middle" font-size="12">Better Housing</text><text x="310" y="55" text-anchor="middle" font-size="12">Commuter Zone</text></svg>`;
 if(kind==="sector")return `<svg viewBox="0 0 620 360"><rect width="620" height="360" rx="18" fill="#fff"/>${title("Sector Model")}<circle cx="310" cy="185" r="140" fill="#f8fafc" stroke="#cbd5e1"/><path d="M310 185 L500 70 A140 140 0 0 1 515 200 Z" fill="#dbeafe"/><path d="M310 185 L120 80 A140 140 0 0 0 130 225 Z" fill="#fee2e2"/><path d="M310 185 L300 325 A140 140 0 0 0 430 285 Z" fill="#dcfce7"/><circle cx="310" cy="185" r="28" fill="#0f172a"/><line x1="90" y1="185" x2="540" y2="185" stroke="#64748b" stroke-width="4" stroke-dasharray="8 6"/><text x="310" y="190" text-anchor="middle" fill="white" font-size="12">CBD</text><text x="450" y="95" text-anchor="middle" font-size="12">High-income sector</text><text x="155" y="115" text-anchor="middle" font-size="12">Industry</text><text x="395" y="310" text-anchor="middle" font-size="12">Residential</text></svg>`;
