 if(kind==="core")return `<svg viewBox="0 0 620 360"><rect width="620" height="360" rx="18" fill="#fff"/>${title("Wallerstein World-Systems")}<circle cx="310" cy="185" r="65" fill="#0f172a"/><circle cx="170" cy="185" r="52" fill="#fef3c7" stroke="#b45309"/><circle cx="450" cy="185" r="52" fill="#fee2e2" stroke="#dc2626"/><path d="M220 185 L245 185" stroke="#334155" stroke-width="3"/><path d="M375 185 L400 185" stroke="#334155" stroke-width="3"/><text x="310" y="190" text-anchor="middle" fill="white" font-size="14" font-weight="900">CORE</text><text x="170" y="190" text-anchor="middle" font-size="12">Semi-periphery</text><text x="450" y="190" text-anchor="middle" font-size="12">Periphery</text><text x="310" y="285" text-anchor="middle" font-size="12">Unequal exchange: raw materials/labor → manufactured goods/profit</text></svg>`;
 return `<svg viewBox="0 0 620 360"><rect width="620" height="360" rx="18" fill="#fff"/>${title("Weber Least-Cost Theory")}<polygon points="150,255 310,80 470,255" fill="#f8fafc" stroke="#334155" stroke-width="3"/><circle cx="150" cy="255" r="30" fill="#fee2e2" stroke="#dc2626"/><circle cx="310" cy="80" r="30" fill="#dbeafe" stroke="#2563eb"/><circle cx="470" cy="255" r="30" fill="#dcfce7" stroke="#16a34a"/><circle cx="310" cy="205" r="34" fill="#0f172a"/><text x="310" y="210" text-anchor="middle" fill="white" font-size="12">Factory</text><text x="150" y="310" text-anchor="middle" font-size="12">Raw materials</text><text x="310" y="55" text-anchor="middle" font-size="12">Market</text><text x="470" y="310" text-anchor="middle" font-size="12">Labor</text><text x="310" y="335" text-anchor="middle" font-size="12">Best location balances transportation + labor + agglomeration costs</text></svg>`;
