function scaleSvg(kind){
 const legend=(items)=>`<div class="gis-legend">${items.map(i=>`<span class="legend-chip"><span class="legend-swatch" style="background:${i[1]}"></span>${i[0]}</span>`).join("")}</div>`;
 if(kind==="globalChoro")return `${legend([["High urbanization","#1e3a8a"],["Medium","#60a5fa"],["Lower","#dbeafe"]])}<svg viewBox="0 0 620 360"><rect width="620" height="360" rx="18" fill="#eff6ff"/><text x="310" y="28" text-anchor="middle" font-size="18" font-weight="900">Global GIS Choropleth: Urbanization</text><ellipse cx="150" cy="150" rx="78" ry="42" fill="#60a5fa" stroke="#334155"/><ellipse cx="300" cy="130" rx="105" ry="46" fill="#1e3a8a" stroke="#334155"/><ellipse cx="465" cy="168" rx="88" ry="42" fill="#60a5fa" stroke="#334155"/><ellipse cx="350" cy="235" rx="72" ry="38" fill="#dbeafe" stroke="#334155"/><circle cx="150" cy="150" r="7" fill="#dc2626"/><circle cx="300" cy="130" r="7" fill="#dc2626"/><circle cx="465" cy="168" r="7" fill="#dc2626"/><text x="310" y="308" text-anchor="middle" font-size="13">Choropleth maps are good for broad patterns, but they hide variation inside each region.</text></svg><div class="map-layer-note"><b>GIS idea:</b> This map layers region boundaries + an urbanization attribute. The darker shade suggests higher urbanization.</div>`;
 if(kind==="nationalDots")return `${legend([["Population cluster","#dc2626"],["Migration flow","#0f172a"],["Lower density","#bfdbfe"]])}<svg viewBox="0 0 620 360"><rect width="620" height="360" rx="18" fill="#eff6ff"/><text x="310" y="28" text-anchor="middle" font-size="18" font-weight="900">National GIS Dot-Density: Population + Migration</text><path d="M95 195 L155 120 L270 102 L365 128 L482 112 L535 178 L492 250 L360 270 L245 238 L135 246 Z" fill="#f8fafc" stroke="#334155" stroke-width="3"/><g fill="#dc2626">${[["150","170"],["160","182"],["172","160"],["410","155"],["430","168"],["445","152"],["460","185"],["485","210"],["330","145"],["345","154"],["255","220"],["265","232"],["390","205"],["405","220"],["505","195"]].map(p=>`<circle cx="${p[0]}" cy="${p[1]}" r="5"/>`).join("")}</g><g stroke="#0f172a" stroke-width="3" fill="none" marker-end="url(#arrow)"><defs><marker id="arrow" markerWidth="10" markerHeight="10" refX="8" refY="3" orient="auto"><path d="M0,0 L0,6 L9,3 z" fill="#0f172a"/></marker></defs><path d="M250 210 C310 190 370 190 430 170"/><path d="M315 240 C370 225 430 218 490 205"/></g><text x="310" y="315" text-anchor="middle" font-size="13">Dots show clusters; arrows show flow. This is stronger than global scale for inside-country patterns.</text></svg><div class="map-layer-note"><b>GIS idea:</b> This combines three layers: country/region outline, population dots, and migration-flow arrows.</div>`;
 if(kind==="localFood")return `${legend([["Low income / low access","#fee2e2"],["Transition/gentrifying","#fef3c7"],["Higher income","#dcfce7"],["Grocery store","#16a34a"],["Transit stop","#2563eb"]])}<svg viewBox="0 0 620 360"><rect width="620" height="360" rx="18" fill="#fff"/><text x="310" y="28" text-anchor="middle" font-size="18" font-weight="900">Local GIS: Food Access + Transit</text><g stroke="#cbd5e1" stroke-width="2">${[90,150,210,270,330,390,450,510].map(x=>`<line x1="${x}" y1="55" x2="${x}" y2="292"/>`).join("")}${[80,130,180,230,280].map(y=>`<line x1="70" y1="${y}" x2="550" y2="${y}"/>`).join("")}</g><rect x="90" y="80" width="140" height="95" fill="#fee2e2" stroke="#dc2626"/><rect x="245" y="80" width="130" height="95" fill="#fef3c7" stroke="#b45309"/><rect x="390" y="80" width="130" height="95" fill="#dcfce7" stroke="#16a34a"/><rect x="110" y="195" width="150" height="70" fill="#fee2e2" stroke="#dc2626"/><rect x="285" y="195" width="210" height="70" fill="#dbeafe" stroke="#2563eb"/><circle cx="440" cy="115" r="10" fill="#16a34a"/><circle cx="480" cy="215" r="10" fill="#16a34a"/><circle cx="320" cy="225" r="8" fill="#2563eb"/><circle cx="375" cy="225" r="8" fill="#2563eb"/><circle cx="430" cy="225" r="8" fill="#2563eb"/><text x="160" y="130" text-anchor="middle" font-size="12">Low grocery access</text><text x="310" y="130" text-anchor="middle" font-size="12">Gentrifying</text><text x="455" y="130" text-anchor="middle" font-size="12">More services</text><text x="185" y="235" text-anchor="middle" font-size="12">Food desert</text><text x="390" y="235" text-anchor="middle" font-size="12">Transit corridor</text></svg><div class="map-layer-note"><b>GIS idea:</b> Local scale lets students overlay income, stores, and transit to explain food deserts or unequal access.</div>`;
 return `${legend([["Global broad pattern","#60a5fa"],["National cluster","#dc2626"],["Local inequality","#fee2e2"]])}<svg viewBox="0 0 620 360"><rect width="620" height="360" rx="18" fill="#fff"/><text x="310" y="28" text-anchor="middle" font-size="18" font-weight="900">Same Issue: Food Access at Three Scales</text><rect x="45" y="70" width="150" height="210" rx="14" fill="#eff6ff" stroke="#94a3b8"/><rect x="235" y="70" width="150" height="210" rx="14" fill="#f8fafc" stroke="#94a3b8"/><rect x="425" y="70" width="150" height="210" rx="14" fill="#fff7ed" stroke="#94a3b8"/><text x="120" y="98" text-anchor="middle" font-size="14" font-weight="900">Global</text><text x="310" y="98" text-anchor="middle" font-size="14" font-weight="900">National</text><text x="500" y="98" text-anchor="middle" font-size="14" font-weight="900">Local</text><ellipse cx="120" cy="170" rx="55" ry="35" fill="#60a5fa"/><path d="M265 200 L305 130 L360 190 Z" fill="#f8fafc" stroke="#334155"/><g fill="#dc2626"><circle cx="287" cy="172" r="5"/><circle cx="313" cy="155" r="5"/><circle cx="340" cy="182" r="5"/></g><rect x="455" y="130" width="80" height="45" fill="#fee2e2" stroke="#dc2626"/><rect x="455" y="195" width="80" height="45" fill="#dcfce7" stroke="#16a34a"/><text x="120" y="245" text-anchor="middle" font-size="11">world regions</text><text x="310" y="245" text-anchor="middle" font-size="11">clusters/flows</text><text x="500" y="245" text-anchor="middle" font-size="11">neighborhood gaps</text></svg><div class="map-layer-note"><b>AP move:</b> A strong answer explains what each scale reveals and what each scale hides.</div>`;
}


function modelsMapsPage(){
 const m=modelBank[selectedModel]||modelBank[0];
 const sp=scalePractice[selectedScale]||scalePractice[0];
 return `<main><section class="card"><h2>🗺️ Models & Maps Preview</h2><p>This preview uses teacher-created SVG diagrams plus GIS-style map practice. No textbook images are embedded.</p><div class="model-map-toolbar"><button class="filter-btn ${modelMapView==="models"?"active":""}" onclick="modelMapView='models';render()">Models</button><button class="filter-btn ${modelMapView==="maps"?"active":""}" onclick="modelMapView='maps';render()">GIS + Scale Maps</button></div><div class="source-note"><b>Map source note:</b> These are simplified classroom GIS diagrams inspired by public-domain/open geographic data conventions such as Natural Earth and U.S. Census TIGER/Line. They are not copied textbook maps.</div></section>${modelMapView==="models"?modelsPanel(m):mapsPanel(sp)}</main>`;
}
function modelsPanel(m){const ex=modelExamples[m.name]||{};return `<section class="card"><h2>📊 APHG Model Bank</h2><div class="model-card-grid"><div class="model-list">${modelBank.map((x,i)=>`<button class="${i===selectedModel?"active":""}" onclick="selectedModel=${i};modelAnswer='';modelFeedback=null;render()"><b>Unit ${x.unit}</b><br>${x.name}<br><small>CED Topic ${x.ced}</small></button>`).join("")}</div><div><span class="pill" style="background:#e0e7ff;color:#3730a3">Unit ${m.unit} • Topic ${m.ced}</span><h2>${m.name}</h2><div class="diagram-wrap">${diagramSvg(m.svg)}</div><div class="model-notes"><div class="box-info"><b>What this model shows</b><p>${m.why}</p></div><div class="box-yellow"><b>What students should look for</b><p>${m.look}</p></div></div><div class="model-example-grid"><div class="box-good"><b>Real-world example</b><p>${ex.example||'Use a specific country, city, or region that fits the model.'}</p></div><div class="box-info"><b>Why it fits</b><p>${ex.why||'Connect the model pattern to evidence from the place.'}</p></div><div class="box-warn"><b>Limitation</b><p>${ex.limit||'No model perfectly explains every real place.'}</p></div><div class="box-yellow"><b>AP move</b><p>Name the model, describe the pattern, apply a place, then explain a limitation.</p></div></div><div class="map-question"><b>Image-based FRQ practice:</b><p>${m.frq}</p></div><textarea class="answer-textarea" style="min-height:110px" placeholder="Write a short FRQ answer. Use because/therefore for explain prompts." oninput="modelAnswer=this.value">${htmlEscape(modelAnswer)}</textarea><div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:10px"><button class="btn-primary" onclick="gradeModelAnswer()">Check my answer</button><button class="btn-secondary" onclick="modelAnswer='';modelFeedback=null;render()">Reset</button><button class="btn-secondary" onclick="masteryView='mixed';active='mastery';render()">Practice mixed FRQ</button></div>${modelFeedback?`<div class="${modelFeedback.ok?"box-good":"box-warn"}" style="margin-top:12px"><b>${modelFeedback.ok?"Likely earns the point":"Needs a rewrite"}</b><p>${modelFeedback.note}</p><p><b>Model answer:</b> ${m.sample}</p></div>`:""}</div></div></section>`}
function realMapHtml(sp){
  if(sp.img==='blackMarble') return `<img class="real-map-img" src="${REAL_MAP_IMAGES.blackMarble}" alt="NASA Black Marble 2016 global night lights map">`;
  if(sp.img==='censusPopulation') return `<img class="real-map-img" src="${REAL_MAP_IMAGES.censusPopulation}" alt="U.S. Census Bureau 2020 population distribution dot map">`;
  if(sp.img==='compareReal') return `<div class="real-map-compare"><img class="real-map-img" src="${REAL_MAP_IMAGES.blackMarble}" alt="NASA Black Marble 2016 global night lights map"><img class="real-map-img" src="${REAL_MAP_IMAGES.censusPopulation}" alt="U.S. Census Bureau 2020 population distribution dot map"></div>`;
  return `<div class="diagram-wrap">${scaleSvg(sp.svg)}</div>`;
}
function mapsPanel(sp){return `<section class="card"><h2>🌍 Real GIS + Scale of Analysis Practice</h2><p>These map stimuli now use actual government/public map sources embedded directly in the app, so they should load even if school devices block external image calls.</p><div class="filter-row">${scalePractice.map((x,i)=>`<button class="filter-btn ${selectedScale===i?"active":""}" onclick="selectedScale=${i};scaleAnswer='';scaleFeedback=null;render()">${x.scale}</button>`).join("")}</div><div class="scale-map-grid"><div class="map-practice-card"><h3>${sp.title}</h3><div class="real-map-wrap">${realMapHtml(sp)}</div><p class="source-note">${sp.source} ${sp.sourceUrl?`<br><a href="${sp.sourceUrl}" target="_blank" rel="noopener">Open source page</a>`:""}</p><div class="map-layer-note"><b>Layers to notice:</b> ${sp.layers.join(" + ")}</div></div><div class="map-practice-card"><h3>AP-style prompt</h3><div class="map-question"><b>${sp.question}</b></div><div class="box-yellow" style="margin:10px 0"><b>Answer recipe</b><p>1. Name the scale. 2. Describe a visible pattern from the map. 3. Explain what this scale hides or reveals compared with another scale.</p></div><textarea class="answer-textarea" style="min-height:150px" placeholder="At the ___ scale, I can see ____. This scale hides/reveals ____ because ____." oninput="scaleAnswer=this.value">${htmlEscape(scaleAnswer)}</textarea><div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:10px"><button class="btn-primary" onclick="gradeScaleAnswer()">Check my answer</button><button class="btn-secondary" onclick="scaleAnswer='';scaleFeedback=null;render()">Reset</button></div>${scaleFeedback?`<div class="${scaleFeedback.ok?"box-good":"box-warn"}" style="margin-top:12px"><b>${scaleFeedback.ok?"Strong AP scale answer":"Needs a more AP-style rewrite"}</b><p>${scaleFeedback.note}</p><p><b>Model answer:</b> ${sp.answer}</p><p><b>Rewrite move:</b> ${scaleFeedback.rewrite}</p></div>`:""}</div></div><section class="card" style="margin-top:18px"><h2>Teacher note</h2><p>This section is built to teach the APHG skill students miss: maps are not just pictures. They are data layers, and the pattern changes depending on scale.</p><div class="callout"><b>Best sentence frame</b><p>Changing the scale of analysis changes the interpretation because broad-scale maps show ____, while local/national-scale maps reveal ____.</p></div></section></section>`}
function gradeModelAnswer(){const txt=(modelAnswer||"").toLowerCase();const ok=txt.length>60&&(txt.includes("because")||txt.includes("therefore")||txt.includes("this leads"))&&txt.match(/model|pattern|stage|market|city|core|periphery|population|cost|distance|urban|birth|death|housing|factory/);modelFeedback={ok:!!ok,note:ok?"You used model language and cause/effect. This is the kind of answer that can earn an FRQ point.":"Add a specific model term and explain cause/effect with because/therefore. Avoid just naming the model."};render();}
function gradeScaleAnswer(){const txt=(scaleAnswer||"").toLowerCase();const hasScale=txt.includes("scale")||txt.includes("global")||txt.includes("local")||txt.includes("regional")||txt.includes("national");const hasPattern=txt.includes("pattern")||txt.includes("cluster")||txt.includes("distribution")||txt.includes("choropleth")||txt.includes("dot")||txt.includes("flow")||txt.includes("access");const hasCompare=txt.includes("hide")||txt.includes("reveal")||txt.includes("visible")||txt.includes("invisible")||txt.includes("compared")||txt.includes("average");const ok=txt.length>70&&hasScale&&hasPattern&&hasCompare;scaleFeedback={ok:!!ok,note:ok?"You named the scale, identified a map pattern, and explained what the scale reveals or hides. That is the APHG skill.":"Add three parts: the scale, a specific pattern from the map, and what that scale hides/reveals compared with another scale.",rewrite:"Use: At the ___ scale, the map shows ____. However, this scale hides/reveals ____ because ____."};render();}

function planPage(){
  const plan=[
    {label:"Start of a unit",focus:"Build the foundation",tasks:"Read the assigned course text, then use Key Terms for the unit. Mark flashcards honestly: Got it only when you can explain the term without looking."},
    {label:"During the unit",focus:"Practice retrieval",tasks:"Complete 8–12 unit MCQs. Read every explanation. For a missed question, say why your choice was wrong and use the correct concept in a because sentence."},
    {label:"After core content",focus:"Apply the geography",tasks:"Use Models & Maps. Identify the model or scale, describe the visible pattern, then explain a geographic relationship using specific evidence."},
    {label:"Before the unit assessment",focus:"FRQ point practice",tasks:"Complete one scaffolded FRQ and one shorter drill. Label every part and match the task verb. Rewrite any response that does not earn the local rubric check."},
    {label:"Every 2–3 weeks",focus:"Spiral old content",tasks:"Take an adaptive mixed quiz. Revisit the two lowest-mastery units and practice their Need Practice flashcards."},
    {label:"After winter break",focus:"Mixed AP practice",tasks:"Begin combining current content with earlier units. Add stimulus questions, population/model/map drills, and one mixed FRQ each week."},
    {label:"6–8 weeks before the AP exam",focus:"Timed sections",tasks:"Use the AP Simulator under realistic timing. Build an error log by unit and skill, then target the patterns you miss most often."},
    {label:"Final week",focus:"Polish, don't cram",tasks:"Review Need Practice vocabulary, models, scale-of-analysis moves, and FRQ task verbs. Do short mixed sets and prioritize sleep and exam-day readiness."}
  ];
  return `<main>
    ${personalizedCoachHtml()}
    <section class="card" style="margin-bottom:18px">
      <h2>📅 2026–27 Study Plan</h2>
      <p>This is a year-long AP Human Geography routine. Use it alongside your class so review stays cumulative instead of turning into a last-minute cram.</p>
      <div class="box-info" style="margin:12px 0"><b>2027 AP exam date:</b> College Board has not published the official AP Human Geography date yet. The site will be updated when it is announced.</div>
    </section>
    <section class="card">
      ${plan.map(d=>`<div class="plan-day"><b>${d.label}</b><div class="focus">Focus: ${d.focus}</div><p>${d.tasks}</p></div>`).join("")}
    </section>
  </main>`;
}

