// QUIZ LOGIC
// ═══════════════════════════════════════════
function chooseAnswer(c){
  if(selectedChoice)return;
  selectedChoice=c;
  const qs=getQuizSet();
  const q=qs[qIndex%qs.length];
  stats.total++;
  const unitLabel=q[0];
  if(!unitStats[unitLabel]) unitStats[unitLabel]={attempted:0,correct:0};
  unitStats[unitLabel].attempted++;
  if(c===q[3]){ stats.correct++; unitStats[unitLabel].correct++; }
  else{missedUnits[unitLabel]=(missedUnits[unitLabel]||0)+1;lastMissed=q;}
  localStorage.setItem("aphgUnitStats",JSON.stringify(unitStats));
  render();
}

function nextQ(){qIndex++;selectedChoice='';render();}

function logReason(reason){
  const box=document.getElementById("reflectionArea");
  if(box) box.innerHTML=`<div class="box-good">Logged: "${reason}." Now read the explanation above and try writing the correct answer in your own words.</div>`;
}

