// TIMER
// ═══════════════════════════════════════════
function startTimer(){
  timedMode=true;timerSeconds=300;
  if(timerInterval)clearInterval(timerInterval);
  timerInterval=setInterval(()=>{
    timerSeconds--;
    if(timerSeconds<=0){clearInterval(timerInterval);timerSeconds=0;}
    const t=document.getElementById("timerBox");
    if(t)t.innerHTML=timerText();
  },1000);
  render();
}
function stopTimer(){timedMode=false;if(timerInterval)clearInterval(timerInterval);render();}
function timerText(){const m=Math.floor(timerSeconds/60),s=String(timerSeconds%60).padStart(2,"0");return `⏱ ${m}:${s}`;}


