// FULL AP SIMULATOR
// ═══════════════════════════════════════════
function simResetAll(){simPhase="intro";simMcqAnswers={};simFrqAnswers={};simFrqFeedback={};simSubmitted=false;simRemaining=0;if(simTimer)clearInterval(simTimer);render();}
function simSelectExam(n){simExam=n;simResetAll();}
function simStart(section){if(simTimer)clearInterval(simTimer);simPhase=section;simRemaining=section==="mcq"?3600:4500;simTimer=setInterval(()=>{simRemaining--;if(simRemaining<=0){clearInterval(simTimer);simRemaining=0;render();}else{const el=document.getElementById("simCountdown");if(el)el.textContent=simTimerText();}},1000);render();}
function simPause(){if(simTimer)clearInterval(simTimer);simTimer=null;render();}
function simTimerText(){const m=Math.floor(simRemaining/60),s=String(simRemaining%60).padStart(2,"0");return `${m}:${s}`;}
function buildSimulatorExam(n){
  const base=buildPracticeExam(n);
  const frq=[{unit:2,title:"Population and Migration",stimuli:[],scenario:"A country is moving from high birth and death rates toward lower death rates while birth rates remain high. Its cities are also receiving large numbers of rural migrants.",parts:[["A","Identify","Identify the demographic model that best explains the country’s population change.","The Demographic Transition Model explains the change."],["B","Describe","Describe one population pattern likely shown by this country’s population pyramid.","The population pyramid would likely have a wide base, showing many young people and high birth rates."],["C","Explain","Explain one challenge this country may face because of rapid urban growth.","Rapid urban growth can strain housing and infrastructure because many migrants arrive faster than governments can provide services."],["D","Explain","Explain one reason rural residents may migrate to cities.","Rural residents may migrate to cities because urban areas offer more jobs, schools, health care, and services."],["E","Describe","Describe one likely effect of a high youth dependency ratio.","A high youth dependency ratio increases demand for schools, child health care, and support from the working-age population."],["F","Explain","Explain how increased educational opportunities for women may affect fertility rates.","Greater educational opportunities can lower fertility because they often delay marriage and childbirth and expand employment choices."],["G","Explain","Explain one way rapid rural-to-urban migration may change the country’s settlement pattern.","Rural-to-urban migration can increase urbanization and the growth of large cities because migrants concentrate near jobs and services."]]},{unit:5,title:"Agricultural Land Use Model",stimuli:["vonthunen"],scenario:"A model shows agricultural activities arranged in rings around a central market.",parts:[["A","Identify","Identify the model shown by the stimulus.","The model is the Von Thünen agricultural land-use model."],["B","Describe","Describe the agricultural pattern shown in the model.","More perishable or expensive-to-transport goods are located closer to the market, while less perishable goods are farther away."],["C","Explain","Explain why dairy or market gardening is close to the market.","Dairy and market gardening are close to the market because these products spoil quickly and cost more to transport over long distances."],["D","Explain","Explain one limitation of the model in the real world.","The model is limited because real landscapes have roads, rivers, mountains, government policies, and multiple markets that change land-use patterns."],["E","Describe","Describe one assumption of the model.","The model assumes an isolated state with uniform terrain, one central market, and transportation costs that rise with distance."],["F","Explain","Explain how refrigeration could alter the model’s land-use pattern.","Refrigeration allows perishable products to travel farther without spoiling, so dairy and market gardening do not have to remain as close to the market."],["G","Explain","Explain how a major highway could change agricultural land values shown by the model.","A highway can lower travel time and transportation cost along its route, increasing the value of accessible land even when it is farther from the market."]]},{unit:6,title:"Urban Inequality and Scale of Analysis",stimuli:["globalChoro","localFood"],scenario:"Two GIS maps show the same issue at different scales: a broad regional pattern of urbanization and a neighborhood map of grocery access, transit, and income.",parts:[["A","Identify","Identify the geographic tool used to layer and analyze the maps.","GIS is the tool used to layer and analyze spatial data."],["B","Describe","Describe one pattern visible at the local scale.","At the local scale, some lower-income neighborhoods have fewer grocery stores or weaker transit access."],["C","Explain","Explain how changing the scale of analysis changes the interpretation.","Changing scale changes interpretation because national or global maps show broad regional patterns, while local maps reveal neighborhood-level inequality that larger scales hide."],["D","Explain","Explain one policy that could reduce the local inequality shown on the map.","A city could improve transit access, incentivize grocery stores, or require mixed-income development because these policies increase access to services for underserved neighborhoods."],["E","Describe","Describe one pattern that the broad regional map may show more clearly than the neighborhood map.","The regional map may show broad concentrations of urbanization or differences among metropolitan regions more clearly than the neighborhood map."],["F","Explain","Explain why the two maps could lead policymakers to different conclusions.","The maps can lead to different conclusions because regional aggregation emphasizes broad trends while local data reveal inequalities hidden within the regional average."],["G","Explain","Explain how the local map could be used to support an environmental-justice decision.","The local map can identify underserved neighborhoods and help direct transit, food access, or infrastructure investment toward populations experiencing unequal access."]]}];
  return{title:`AP Simulator ${n}`,mcq:base.mcq,frq};
}
function simSetMcq(i,choice){if(simSubmitted)return;simMcqAnswers[i]=choice;render();}
function simSetFrq(i,val){simFrqAnswers[i]=val;}
function simSubmit(){if(simTimer)clearInterval(simTimer);const exam=buildSimulatorExam(simExam);simFrqFeedback={};exam.frq.forEach((p,i)=>simFrqFeedback[i]=gradeOneFrq(p,simFrqAnswers[i]||""));simSubmitted=true;simPhase="results";render();}
function simResultsHtml(exam){const mcqCorrect=exam.mcq.filter((q,i)=>simMcqAnswers[i]===q.answer).length;const frqEarned=Object.values(simFrqFeedback).reduce((sum,f)=>sum+(f?f.score:0),0);const frqPossible=Object.values(simFrqFeedback).reduce((sum,f)=>sum+(f?f.total:0),0)||21;const est=estimateApScore(mcqCorrect,frqEarned,frqPossible);const missedByUnit={};exam.mcq.forEach((q,i)=>{if(simMcqAnswers[i]!==q.answer)missedByUnit[q.unit]=(missedByUnit[q.unit]||0)+1;});const weakRows=Object.entries(missedByUnit).sort((a,b)=>b[1]-a[1]).slice(0,4).map(([u,n])=>`<div class="readiness-action"><b>Unit ${u}: ${n} missed</b><p>Study flashcards, then answer 5 MCQs and one FRQ part from this unit.</p></div>`).join("")||`<div class="box-good">No major MCQ weak spot found.</div>`;return `<section class="card"><h2>🎓 AP Simulator Score Report</h2><div class="sim-report-grid"><div class="sim-report-card"><b>${mcqCorrect}/60</b><span>MCQ raw</span></div><div class="sim-report-card"><b>${frqEarned}/${frqPossible}</b><span>FRQ estimate</span></div><div class="sim-report-card"><b>${est.composite}/120</b><span>composite</span></div><div class="sim-report-card"><b>${est.ap}</b><span>AP score estimate</span></div></div><div class="box-yellow"><b>Important:</b> This is a practice estimate, not an official College Board score. Real cut scores change each year.</div><h3>What to study next</h3>${weakRows}</section>`;}
function simIntroPage(){return `<main><section class="sim-hero"><h2>🎓 Full AP Human Geography Simulator</h2><p>This mode is built to feel closer to the real AP structure: timed sections, stimulus-based MCQs, three FRQs, and a score report.</p><div class="sim-status"><span>Section I: 60 MCQs / 60 minutes</span><span>Section II: 3 FRQs / 75 minutes</span><span>MCQ = 50%</span><span>FRQ = 50%</span></div></section><section class="card"><h2>Choose a simulator version</h2><div class="filter-row">${[1,2,3].map(n=>`<button class="filter-btn ${simExam===n?'active':''}" onclick="simSelectExam(${n})">Simulator ${n}</button>`).join("")}</div><div class="box-info"><b>Student directions</b><p>Start with MCQ. When finished, move to FRQ. The score report appears after final submission and shows missed concepts, why answers were wrong, and rewrite suggestions.</p></div><div style="display:flex;gap:10px;flex-wrap:wrap;margin-top:14px"><button class="btn-primary" onclick="simStart('mcq')">Start Section I: MCQ</button><button class="btn-secondary" onclick="simStart('frq')">Skip to FRQ practice</button></div></section></main>`;}
function simMcqPage(){const exam=buildSimulatorExam(simExam);const answered=Object.keys(simMcqAnswers).length;return `<main><div class="sim-timer"><span><b id="simCountdown">${simTimerText()}</b> Section I: Multiple Choice</span><div><button class="btn-sm btn-secondary" onclick="simPause()">Pause</button> <button class="btn-sm btn-primary" onclick="simStart('frq')">Go to FRQ</button></div></div><section class="card"><h2>${exam.title}: Section I</h2><p>Answer 60 questions. Some include map/data/model stimulus cues, like the digital AP exam.</p><div class="sim-nav-grid">${exam.mcq.map((q,i)=>`<button class="sim-bubble ${simMcqAnswers[i]?'done':''}" onclick="document.getElementById('simq${i}').scrollIntoView({behavior:'smooth'})">${i+1}</button>`).join("")}</div><p><b>${answered}/60 answered</b></p></section><section class="card">${exam.mcq.map((q,i)=>`<div class="exam-question" id="simq${i}"><b>${i+1}. ${q.q}</b>${q.stimulus?q.stimulus.html:''}<div style="margin-top:8px">${q.choices.map((c,ci)=>`<button class="exam-choice ${simMcqAnswers[i]===c?'selected':''}" onclick="simSetMcq(${i},'${String(c).replace(/'/g,"\\'")}')"><b>${['A','B','C','D'][ci]}.</b> ${c}</button>`).join("")}</div></div>`).join("")}</section><section class="card"><button class="btn-primary" onclick="simStart('frq')">Finish MCQ and start FRQ section</button></section></main>`;}
function simFrqStimuliHtml(p){if(!p.stimuli||!p.stimuli.length)return '';return `<div class="grid2">${p.stimuli.map(st=>`<div class="sim-stimulus"><b>Stimulus</b><div class="diagram-wrap">${diagramSvg(st)||scaleSvg(st)}</div></div>`).join("")}</div>`;}
function simFrqPage(){const exam=buildSimulatorExam(simExam);return `<main><div class="sim-timer"><span><b id="simCountdown">${simTimerText()}</b> Section II: Free Response</span><div><button class="btn-sm btn-secondary" onclick="simPause()">Pause</button> <button class="btn-sm btn-primary" onclick="simSubmit()">Submit full simulator</button></div></div><section class="card"><h2>${exam.title}: Section II</h2><p>Write short labeled answers. This is not a five-paragraph essay. Label A through G and use <b>because</b> for explain prompts.</p><div class="box-yellow"><b>FRQ structure:</b> Q1 text only. Q2 has one stimulus. Q3 has two stimuli and scale-of-analysis practice.</div></section>${exam.frq.map((p,i)=>`<section class="card"><h2>FRQ ${i+1}: ${p.title}</h2><span class="pill" style="background:#e0e7ff;color:#3730a3">Unit ${p.unit}</span><div class="scenario-box"><b>Scenario</b><p>${p.scenario}</p></div>${simFrqStimuliHtml(p)}${p.parts.map(part=>`<div class="sim-frq-part"><b>${part[0]}. ${part[1]}</b><p>${part[2]}</p><p class="frame-hint">Point move: ${part[1]==='Explain'?'Use because/therefore and show cause-effect.':part[1]==='Describe'?'Give one clear characteristic or pattern.':'Name the correct term or concept.'}</p></div>`).join("")}<textarea class="answer-textarea" placeholder="Label your answers A, B, C, D, E, F, G..." oninput="simSetFrq(${i},this.value)">${htmlEscape(simFrqAnswers[i]||"")}</textarea></section>`).join("")}<section class="card"><button class="btn-primary" onclick="simSubmit()">Submit and get AP-style score report</button><button class="btn-secondary" onclick="simResetAll()">Reset simulator</button></section></main>`;}
function simResultsPage(){const exam=buildSimulatorExam(simExam);return `<main>${simResultsHtml(exam)}<section class="card"><h2>Multiple Choice Review</h2>${exam.mcq.map((q,i)=>`<div class="exam-question"><b>${i+1}. ${q.q}</b>${q.stimulus?q.stimulus.html:''}<div class="${simMcqAnswers[i]===q.answer?'explain-good':'explain-bad'} explain-box"><b>${simMcqAnswers[i]===q.answer?'Correct':'Correct answer: '+q.answer}</b><br>${q.why}<br><b>Your answer:</b> ${simMcqAnswers[i]||'blank'}</div></div>`).join("")}</section><section class="card"><h2>FRQ Review + Rewrite Help</h2>${exam.frq.map((p,i)=>`<div class="exam-frq"><h3>FRQ ${i+1}: ${p.title}</h3>${simFrqFeedback[i]?`<div class="box-info"><b>Estimated score: ${simFrqFeedback[i].score}/${simFrqFeedback[i].total}</b>${simFrqFeedback[i].parts.map(r=>`<div class="part-result ${r.earned?'part-earned':'part-missing'}"><b>${r.earned?'✅':'⬜'} Part ${r.part}</b><br>${r.note}<div class="part-fix"><b>Rewrite/model:</b> ${r.fix}</div></div>`).join("")}</div>`:''}</div>`).join("")}</section><section class="card"><button class="btn-primary" onclick="simResetAll()">Try another simulator</button></section></main>`;}
function apSimulatorPage(){if(simPhase==="mcq")return simMcqPage();if(simPhase==="frq")return simFrqPage();if(simPhase==="results")return simResultsPage();return simIntroPage();}


