// AP MASTERY TOOL: visual pyramid drills + mixed map/model FRQs + pathway
// ═══════════════════════════════════════════
const modelExamples={
 "Demographic Transition Model":{example:"Niger as a Stage 2 example; Germany or Japan as Stage 4/5 examples.",why:"Niger has high birth rates and falling death rates, while Germany/Japan have low fertility and aging populations.",limit:"The DTM assumes countries move through stages in a similar order, but war, policy, migration, and disease can change the pattern."},
 "Population Pyramid":{example:"Niger/Uganda = youthful rapid growth; United States/France = slow growth; Japan/Germany/Italy = aging; Russia/Bulgaria = decline; Syria/Ukraine can show irregular cohorts from conflict or migration.",why:"The shape shows age structure: a wide base signals high birth rates, while a narrow base and larger older cohorts show aging or decline.",limit:"A pyramid does not directly show causes; students must connect shape to fertility, mortality, migration, or historical events."},
 "Von Thünen Agricultural Model":{example:"Dairy farms and market gardening near large urban markets in the northeastern United States.",why:"Perishable or heavy products locate near markets because spoilage and transportation costs are high.",limit:"The model assumes flat land, one market, equal transportation, and no government policy, which is rarely true."},
 "Concentric Zone Model":{example:"Historical Chicago is the classic example used with Burgess’s model.",why:"Industrial-era cities expanded outward in rings from a CBD, with older housing and industry near the center.",limit:"Modern cities are shaped by highways, zoning, suburbs, and multiple centers, so rings are often imperfect."},
 "Sector Model":{example:"Chicago-style high-rent or industrial sectors extending along rail lines, highways, or lakefront corridors.",why:"Land uses often grow outward along transportation corridors rather than perfect circles.",limit:"It works less well in cities without dominant transit corridors or where policy strongly shapes development."},
 "Multiple Nuclei Model":{example:"Los Angeles, with Downtown LA, Hollywood, Santa Monica, Irvine/Orange County, and airport/industrial nodes.",why:"Large cities often have multiple centers of employment, retail, entertainment, and industry.",limit:"The boundaries between nodes can be fuzzy, and the model can be harder for students to label clearly."},
 "Latin American City Model":{example:"Mexico City, where wealthier development may extend along a commercial spine while informal settlements appear on the urban edge.",why:"Colonial history, rapid urbanization, and inequality shape land-use patterns.",limit:"Not every Latin American city follows the model, and newer development can change the pattern."},
 "Rostow's Stages of Growth":{example:"South Korea is often used as an example of rapid industrialization and movement toward high mass consumption.",why:"Investment, manufacturing growth, exports, and technology helped transform the economy.",limit:"The model is criticized for assuming all countries can follow the same path and for ignoring colonialism and unequal trade."},
 "Wallerstein World-Systems":{example:"United States/Germany/Japan as core areas; parts of Sub-Saharan Africa or Latin America as periphery/semi-periphery depending on industry and trade.",why:"Core countries control high-value production while peripheral areas often export raw materials or low-wage labor.",limit:"It can oversimplify countries and does not always capture rapid development or regional variation."},
 "Weber Least-Cost Theory":{example:"Steel mills historically located near coal and iron ore in Pennsylvania and the Great Lakes region.",why:"Bulky raw materials made transportation costs important, so firms located where total costs were lower.",limit:"Modern footloose industries, container shipping, and technology reduce the importance of raw-material location."}
};

const pyramidDrills=[
 {type:"rapid",name:"Rapid Growth / Expansive",places:"Niger, Uganda, Afghanistan",answer:"Rapid Growth / Expansive",choices:["Rapid Growth / Expansive","Stable / Slow Growth","Aging / Contracting","Irregular / Migration Impact"],describe:"Wide base with many children and a narrow top.",explain:"This suggests high birth rates and future growth because a large share of the population has not reached reproductive age.",ap:"Often connects to DTM Stage 2, youth dependency, school demand, and future job pressure."},
 {type:"stable",name:"Stable / Slow Growth",places:"United States, France",answer:"Stable / Slow Growth",choices:["Declining / Negative Growth","Stable / Slow Growth","Rapid Growth / Expansive","War Impact / Missing Cohort"],describe:"More rectangular sides with a balanced working-age population.",explain:"This suggests slower growth because birth and death rates are relatively low and more balanced.",ap:"Often connects to DTM Stage 3/4, moderate dependency, and stable labor supply."},
 {type:"aging",name:"Aging / Contracting",places:"Japan, Germany, Italy",answer:"Aging / Contracting",choices:["Rapid Growth / Expansive","Aging / Contracting","Youthful Population","High Immigration Only"],describe:"Narrow base with relatively larger older cohorts.",explain:"This suggests low fertility and an aging population because fewer children are being born to replace older generations.",ap:"Often connects to pensions, health care, elderly dependency, and pronatalist policy."},
 {type:"decline",name:"Declining / Negative Growth",places:"Russia, Bulgaria, parts of Eastern Europe",answer:"Declining / Negative Growth",choices:["Declining / Negative Growth","Rapid Growth / Expansive","Stable / Slow Growth","Stage 2 Growth"],describe:"Small younger cohorts compared with middle or older cohorts.",explain:"This suggests population decline because births are not replacing the existing population.",ap:"Often connects to labor shortages, shrinking tax base, and aging infrastructure demands."},
 {type:"irregular",name:"Irregular / Migration or Conflict Impact",places:"Syria, Ukraine, Gulf states with labor migration",answer:"Irregular / Migration or Conflict Impact",choices:["Stable / Slow Growth","Irregular / Migration or Conflict Impact","Rapid Growth / Expansive","Concentric Zone Pattern"],describe:"Uneven bulges, gaps, or one sex/age cohort larger than expected.",explain:"This suggests a historical disruption because war, disease, or migration can remove or add specific cohorts.",ap:"Often connects to refugees, guest workers, gender imbalance, or missing cohorts after conflict."}
];

function pyramidSvg(type){
 const rows=["75+","65-74","55-64","45-54","35-44","25-34","15-24","0-14"];
 const widths={rapid:[18,28,42,58,78,102,132,168],stable:[72,82,92,100,104,108,112,116],aging:[116,128,124,112,92,70,54,42],decline:[110,124,126,116,94,72,48,34],irregular:[60,90,70,120,52,140,86,126]}[type]||[50,70,90,110,130,150,170,190];
 return `<svg class="pyramid-svg" viewBox="0 0 640 430" role="img" aria-label="population pyramid"><rect width="640" height="430" rx="18" fill="#ffffff"/><text x="320" y="30" text-anchor="middle" font-size="20" font-weight="900">Population Pyramid Practice</text><text x="230" y="60" text-anchor="middle" font-weight="700">Male</text><text x="410" y="60" text-anchor="middle" font-weight="700">Female</text><line x1="320" y1="70" x2="320" y2="375" stroke="#334155" stroke-width="2"/>${rows.map((r,i)=>{const y=82+i*36,w=widths[i];return `<text x="55" y="${y+16}" font-size="13" fill="#475569">${r}</text><rect x="${320-w}" y="${y}" width="${w}" height="24" fill="#dbeafe" stroke="#60a5fa"/><rect x="320" y="${y}" width="${w}" height="24" fill="#dcfce7" stroke="#22c55e"/>`;}).join("")}<text x="320" y="405" text-anchor="middle" font-size="13" fill="#475569">Read the base, middle, top, and any missing/bulging cohorts.</text></svg>`;
}

function getMasterySnapshot(){
 const attempted=stats.total||0;
 const accuracy=attempted?Math.round(stats.correct/attempted*100):0;
 const weak=getWeakestUnit();
 const flashNeed=flashcards.filter(c=>flashProgress[flashKey(c)]!=="got").length;
 return {attempted,accuracy,weak,flashNeed};
}

function apMasteryPage(){
 const snap=getMasterySnapshot();
 if(masteryView==="pyramids") return pyramidDrillsPage();
 if(masteryView==="mixed") return mixedFrqPage();
 if(masteryView==="exams") return `<main><section class="card"><h2>🎓 Full AP Practice</h2><p>Use these after students have done targeted practice. The simulator keeps AP timing and gives an estimated score report.</p><div class="mastery-actions"><button class="btn-primary" onclick="go('simulator')">Open AP Simulator</button><button class="btn-secondary" onclick="go('practice')">Open Practice Exams</button><button class="btn-secondary" onclick="masteryView='dashboard';render()">Back to Mastery</button></div></section></main>`;
 return `<main><section class="card"><h2>🏆 AP Mastery Dashboard</h2><p>This is the student pathway: diagnose, practice the weak skill, then prove it with AP-style questions.</p><div class="mastery-grid"><div class="mastery-tile"><b>${snap.accuracy||'—'}%</b><span>Quiz accuracy</span><p>${snap.attempted} MCQs attempted</p></div><div class="mastery-tile"><b>${snap.weak?`Unit ${snap.weak.unit}`:'No weak unit yet'}</b><span>Current target</span><p>${snap.weak?snap.weak.name:'Take an adaptive quiz to find one.'}</p></div><div class="mastery-tile"><b>${snap.flashNeed}</b><span>Vocab cards not mastered</span><p>Use Key Terms → Flashcards.</p></div></div><div class="box-yellow"><b>Recommended next step:</b> ${snap.weak?`Practice Unit ${snap.weak.unit} with an adaptive quiz, then complete one matching FRQ.`:'Start with a 10-question adaptive quiz.'}</div><div class="mastery-actions"><button class="btn-primary" onclick="startAdaptiveQuiz()">Start adaptive quiz</button><button class="btn-secondary" onclick="masteryView='pyramids';render()">📊 Pyramid drills</button><button class="btn-secondary" onclick="masteryView='mixed';render()">🗺️ Mixed map/model FRQs</button><button class="btn-secondary" onclick="go('models')">Study models & real GIS maps</button><button class="btn-danger" onclick="masteryView='exams';render()">Take full AP practice</button></div></section><section class="card"><h2>Efficient 20-minute path</h2><div class="readiness-checks"><button class="check-btn" onclick="startAdaptiveQuiz()">1. Answer 10 adaptive MCQs</button><button class="check-btn" onclick="masteryView='pyramids';render()">2. Do one pyramid drill</button><button class="check-btn" onclick="masteryView='mixed';render()">3. Write one mixed stimulus FRQ</button><button class="check-btn" onclick="go('terms');termView='flashcards';flashMode='need';render()">4. Review only missed vocab</button></div></section></main>`;
}

function pyramidDrillsPage(){
 const p=pyramidDrills[pyramidDrillIndex%pyramidDrills.length];
 return `<main><section class="card"><div class="mastery-mini-nav"><button class="btn-secondary btn-sm" onclick="masteryView='dashboard';render()">← Mastery Dashboard</button><button class="btn-secondary btn-sm" onclick="pyramidSelected='';pyramidFeedback=null;pyramidDrillIndex=(pyramidDrillIndex+1)%pyramidDrills.length;render()">Next pyramid</button></div><h2>📊 Population Pyramid Drill</h2><p>Goal: identify the shape quickly, then describe and explain it in AP language.</p><div class="pyramid-practice-layout"><div class="pyramid-visual">${pyramidSvg(p.type)}<div class="box-info"><b>Possible locations:</b> ${p.places}</div></div><div><h3>A. Identify the pyramid type</h3>${p.choices.map(c=>`<button class="mastery-choice ${pyramidSelected===c?'selected':''} ${pyramidFeedback&&(c===p.answer?'correct':pyramidSelected===c&&c!==p.answer?'wrong':'')}" onclick="selectPyramidAnswer('${c.replace(/'/g,"\'")}')">${c}</button>`).join('')}<h3>B. Describe one feature</h3><div class="box-yellow">Use: “The pyramid has ___, which shows ___.”</div><h3>C. Explain one consequence</h3><div class="box-yellow">Use: “This creates ___ because ___.”</div>${pyramidFeedback?`<div class="${pyramidFeedback.ok?'box-good':'box-warn'}" style="margin-top:12px"><b>${pyramidFeedback.ok?'Correct':'Not quite'}</b><p>${pyramidFeedback.note}</p><p><b>Describe:</b> ${p.describe}</p><p><b>Explain:</b> ${p.explain}</p><p><b>AP use:</b> ${p.ap}</p></div>`:''}</div></div></section></main>`;
}
function selectPyramidAnswer(choice){const p=pyramidDrills[pyramidDrillIndex%pyramidDrills.length];pyramidSelected=choice;pyramidFeedback={ok:choice===p.answer,note:choice===p.answer?`Yes — this is a ${p.answer} pyramid.`:`Correct answer: ${p.answer}. Look at the base first, then the middle and top.`};render();}

const mixedStimulusFrqs=[
 {title:"Population Pyramid + DTM",unit:2,visual:"rapid",parts:[
  {label:"A",task:"Identify",q:"Identify the population pyramid pattern shown.",must:["rapid","expansive","wide base","growth"],model:"The pyramid shows rapid growth/expansive structure because it has a wide base."},
  {label:"B",task:"Describe",q:"Describe one feature of the population structure.",must:["wide","young","children","base"],model:"One feature is a wide base, meaning the population has many young people."},
  {label:"C",task:"Explain",q:"Explain one future challenge this country may face.",must:["because","school","jobs","dependency","housing","services"],model:"The country may struggle to provide schools and jobs because a large youth population will need education and employment."}
 ]},
 {title:"Von Thünen + Market Distance",unit:5,visual:"vonthunen",parts:[
  {label:"A",task:"Identify",q:"Identify the agricultural model shown.",must:["von","thunen","thünen"],model:"The model is the Von Thünen agricultural land-use model."},
  {label:"B",task:"Describe",q:"Describe the pattern of agricultural land use.",must:["rings","market","closer","distance"],model:"Agricultural activities are arranged in rings around a central market."},
  {label:"C",task:"Explain",q:"Explain why dairy or market gardening is close to the market.",must:["because","perishable","spoil","transport","cost"],model:"Dairy is close to the market because it spoils quickly and costs more to transport over long distances."}
 ]},
 {title:"Real GIS Map + Scale of Analysis",unit:1,visual:"map",parts:[
  {label:"A",task:"Identify",q:"Identify the geographic tool used to layer and analyze spatial data.",must:["gis","geographic information"],model:"GIS is used to layer and analyze spatial data."},
  {label:"B",task:"Describe",q:"Describe one spatial pattern visible at a broad scale.",must:["cluster","pattern","urban","coastal","uneven","distribution"],model:"At a broad scale, population and light are clustered in urban/coastal areas rather than evenly distributed."},
  {label:"C",task:"Explain",q:"Explain how changing scale changes interpretation.",must:["because","scale","local","global","hide","reveal"],model:"Changing scale changes interpretation because global maps show broad patterns while local maps reveal neighborhood-level differences that broad maps hide."}
 ]}
];
function mixedVisual(frq){ if(frq.visual==="rapid") return pyramidSvg("rapid"); if(frq.visual==="vonthunen") return diagramSvg("vonthunen"); return actualMapMedia(actualMapPractice[0]); }
function mixedFrqPage(){const f=mixedStimulusFrqs[mixedFrqIndex%mixedStimulusFrqs.length];return `<main><section class="card"><div class="mastery-mini-nav"><button class="btn-secondary btn-sm" onclick="masteryView='dashboard';render()">← Mastery Dashboard</button><button class="btn-secondary btn-sm" onclick="mixedFrqIndex=(mixedFrqIndex+1)%mixedStimulusFrqs.length;mixedAnswers={};mixedFeedback=null;render()">Next mixed FRQ</button></div><h2>🗺️ Mixed Stimulus FRQ</h2><p>These combine models, maps, and AP command verbs.</p><div class="pyramid-practice-layout"><div class="pyramid-visual">${mixedVisual(f)}</div><div><span class="pill" style="background:#e0e7ff;color:#3730a3">Unit ${f.unit}</span><h3>${f.title}</h3>${f.parts.map(part=>`<div class="rubric-row"><b>${part.label}. ${part.task}:</b> ${part.q}<div class="frame-hint">${part.task==='Explain'?'Use because/therefore.':'Answer directly and use APHG vocabulary.'}</div><textarea class="answer-textarea" style="min-height:72px" placeholder="Answer part ${part.label}..." oninput="mixedAnswers['${part.label}']=this.value">${htmlEscape(mixedAnswers[part.label]||'')}</textarea>${mixedFeedback?renderMixedPartFeedback(part,mixedAnswers[part.label]||''):''}</div>`).join('')}<button class="btn-primary" onclick="gradeMixedFrq()">Check this FRQ</button><button class="btn-secondary" onclick="mixedAnswers={};mixedFeedback=null;render()">Reset</button></div></div></section></main>`;}
function gradeMixedFrq(){mixedFeedback=true;render();}
function renderMixedPartFeedback(part,ans){const t=(ans||'').toLowerCase();const hits=part.must.filter(k=>t.includes(k)).length;const ok=hits>=1 && (part.task!=='Explain'||/(because|therefore|this leads|as a result)/.test(t));return `<div class="${ok?'box-good':'box-warn'}" style="margin-top:8px"><b>${ok?'✅ Earned the point':'⬜ Not yet'}</b><p>${ok?'Your answer includes the required idea.':'To earn the point, include the key concept and show cause/effect when asked to explain.'}</p><p><b>Show me how to rewrite:</b> ${part.model}</p></div>`;}


